          time_offsets_s: [5, 20, 35, 50],
          allow_reauth: true
        },
        link_state: {
          comm_range_m: 320
        }
      },
      { 
        id: 1, 
        mobility: { 
          type: 'gauss_markov_3d',
          seed: 20260418,
          alpha: 0.7,
          mean_speed_mps: 5.0,
          speed_std_mps: 5.0,
          mean_altitude_m: 80.0,
          altitude_std_m: 20.0,
          area_size_x: 600.0,
          area_size_y: 600.0,
          min_altitude_m: 30.0,
          max_altitude_m: 200.0,
          initial_position: [100, 50, 75.0],
          initial_velocity: [-1.5, 1.0, -0.3],
